fn median_of(vals: List[Int]) -> Float {
  let sorted = vals.sort()
  let m = sorted.len()
  let mid = m / 2
  if m % 2 == 1 {
    return sorted.get_or(mid, 0).to_float()
  }
  return (sorted.get_or(mid - 1, 0).to_float() + sorted.get_or(mid, 0).to_float()) / 2.0
}

pub fn medians(xs: List[Int], k: Int) -> List[Float] {
  let n = xs.len()
  if k < 1 or k > n {
    return []
  }
  let starts = range(0, n - k + 1)
  return starts.map(fn(i) => median_of(xs.slice(i, i + k)))
}
